--
-- Table structure for table `Moment`
--

DROP TABLE IF EXISTS `Moment`;
CREATE TABLE `Moment` (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `userId` bigint NOT NULL COMMENT '用户id',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `content` varchar(300) DEFAULT NULL COMMENT '内容',
  `praiseUserIdList` json NOT NULL COMMENT '点赞的用户id列表',
  `pictureList` json NOT NULL COMMENT '图片列表',
  PRIMARY KEY (`id`)
);

CREATE INDEX `idx_Moment_userId` ON `Moment` (`userId`,`date`);
CREATE INDEX `idx_Moment_index_date` ON `Moment` (`date`);

