--
-- Table structure for table `Comment`
--

DROP TABLE IF EXISTS `Comment`;
CREATE TABLE `Comment` (
  `id` bigint NOT NULL COMMENT '主键',
  `toId` bigint NOT NULL DEFAULT '0' COMMENT '被回复的id',
  `userId` bigint NOT NULL COMMENT '评论人 User 的 id',
  `momentId` bigint NOT NULL COMMENT '动态id',
  `date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建日期',
  `content` varchar(1000) NOT NULL COMMENT '内容',
  PRIMARY KEY (`id`)
);

CREATE INDEX `idx_Comment_index_date` ON `Comment` (`date`);
CREATE INDEX `idx_Comment_index_userId` ON `Comment` (`userId`);
CREATE INDEX `idx_Comment_index_moment` ON `Comment` (`momentId`);
CREATE INDEX `idx_Comment_index_toId` ON `Comment` (`toId`);

