DROP TABLE IF EXISTS `Verify`;
CREATE TABLE `Verify` (
  `id` bigint NOT NULL COMMENT '唯一标识',
  `type` int NOT NULL DEFAULT '0' COMMENT '类型：\n0-登录\n1-注册\n2-修改登录密码\n3-修改支付密码',
  `phone` bigint NOT NULL COMMENT '手机号',
